<template>
  <div class="storefront-page" v-loading="loading">
    <el-button text @click="router.push(shopPath)"><i class="ph ph-arrow-left" /> 返回周边商城</el-button>
    <template v-if="merchant">
      <section class="store-cover" :style="merchant.coverUrl ? {backgroundImage:`linear-gradient(90deg, #122a29bb, #122a2922),url(${merchant.coverUrl})`} : {}"><span class="store-cover-label">CAMPUS PARTNER · 校园合作商家</span><div class="store-identity"><el-avatar :size="86" :src="merchant.avatar || undefined">{{ merchant.name?.slice(0,1) }}</el-avatar><div><h1>{{ merchant.name }}</h1><p><i class="ph ph-map-pin" /> {{ merchant.city }}发货 <span>·</span> <i class="ph ph-seal-check" /> 平台合作商家</p></div></div></section>
      <section class="store-metrics"><div><small>商家综合评分</small><strong>{{ Number(merchant.rating)>0 ? Number(merchant.rating).toFixed(1) : '暂无评分' }} <span v-if="Number(merchant.rating)>0">/ 5</span></strong><el-rate v-if="Number(merchant.rating)>0" :model-value="Number(merchant.rating)" disabled allow-half /><p>{{ merchant.reviewCount }} 条购买评价</p></div><div><small>发货位置</small><strong class="city-value"><i class="ph ph-map-pin" /> {{ merchant.city }}</strong><p>商品从商家填写的城市发出</p></div><div><small>在售商品</small><strong>{{ products.length }} <span>件</span></strong><p>累计订单 {{ merchant.sales }} 笔</p></div></section>
      <section class="store-catalog"><header><div><h2>店铺全部商品 <span>{{ products.length }}</span></h2><p>发现这家店里的每一份好物。</p></div><el-input v-model="keyword" clearable maxlength="100" placeholder="搜索本店商品" aria-label="搜索本店商品" size="large"><template #prefix><i class="ph ph-magnifying-glass" /></template></el-input></header><div v-if="filtered.length" class="store-product-grid"><RouterLink v-for="p in filtered" :key="p.adId" :to="`${shopPath}/product/${p.adId}`" class="store-product"><img :src="p.imageUrl" :alt="p.title" loading="lazy" /><div><h3>{{ p.title }}</h3><p>{{ p.content }}</p><footer><strong>¥ {{ Number(p.price).toFixed(2) }}</strong><span>{{ Number(p.score)>0?'评分 '+Number(p.score).toFixed(1):'暂无评价' }}</span></footer></div></RouterLink></div><el-empty v-else :description="keyword?'没有找到匹配的商品':'商家暂时没有上架商品'" /></section>
    </template>
    <el-empty v-else-if="!loading" :description="banned?'该商家已被封禁，所有商品已下架，广告已撤销':'店铺不存在或已暂停营业'"><el-button type="primary" @click="router.push(shopPath)">返回周边商城</el-button></el-empty>
  </div>
</template>
<script setup>
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { getRole } from '@/utils/auth'
import { fetchMerchantStore } from '@/api/merchant'
const route=useRoute(),router=useRouter(),shopPath=`/${getRole().toLowerCase()}/shop`,merchant=ref(null),products=ref([]),keyword=ref(''),loading=ref(false)
const banned=ref(false)
const filtered=computed(()=>products.value.filter(p=>`${p.title} ${p.content}`.toLowerCase().includes(keyword.value.trim().toLowerCase())))
let version=0
async function load(){const stamp=++version;loading.value=true;merchant.value=null;banned.value=false;keyword.value='';try{const r=await fetchMerchantStore(route.params.merchantId);if(stamp!==version)return;merchant.value=r.data.merchant;products.value=r.data.products}catch(e){if(stamp===version)banned.value=e.response?.data?.data?.type==='MERCHANT_STOREFRONT_BANNED'}finally{if(stamp===version)loading.value=false}}
watch(()=>route.params.merchantId,load,{immediate:true})
</script>
<style scoped>
.storefront-page{max-width:1280px;margin:0 auto}.storefront-page>.el-button{margin-bottom:15px;color:#8996a1;gap:8px}.store-cover{min-height:265px;border-radius:22px;padding:34px 38px;background:linear-gradient(120deg,#31544c,#77876c);background-size:cover;background-position:center;display:flex;flex-direction:column;justify-content:space-between;gap:45px;overflow:hidden;color:#fff}.store-cover-label{font-size:10px;letter-spacing:2px;color:#e3e9d8}.store-identity{display:flex;align-items:center;gap:22px}.store-identity :deep(.el-avatar){border:3px solid #ffffff90;box-shadow:0 8px 24px #102b2330;background:#faf5de;color:#8f9a67;font-size:30px;flex-shrink:0}.store-identity h1{font-size:28px;margin:0 0 14px;text-shadow:0 2px 12px #0002;overflow-wrap:anywhere}.store-identity p{display:flex;align-items:center;flex-wrap:wrap;gap:9px;font-size:12px;color:#f4f5ec;margin:0}.store-identity p span{margin:0 5px;opacity:.5}.store-metrics{display:grid;grid-template-columns:1fr 1.4fr 1fr;margin:22px 0 32px;border:1px solid #ebedf0;border-radius:18px;background:#fff;padding:26px}.store-metrics>div{padding:0 25px;border-right:1px solid #edf0f2}.store-metrics>div:last-child{border:0}.store-metrics small{font-size:12px;color:#929daa;display:block;margin-bottom:12px}.store-metrics strong{font-size:29px;color:#40524b;font-weight:600;display:block}.store-metrics strong span{font-size:12px;font-weight:400;color:#a6b0ab}.store-metrics .city-value{font-size:20px;line-height:1.7}.store-metrics .city-value i{font-size:18px;color:var(--theme-primary)}.store-metrics p{font-size:11px;color:#a4adb5;margin:10px 0 0}.store-metrics :deep(.el-rate){height:25px;--el-rate-icon-size:14px;--el-rate-fill-color:#d3ad62}.store-catalog>header{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:23px}.store-catalog h2{margin:0;font-size:21px}.store-catalog h2 span{font-size:13px;color:#a6afb9;font-weight:400;margin-left:7px}.store-catalog>header p{font-size:12px;color:#9ca6af;margin:9px 0 0}.store-catalog>header .el-input{max-width:300px}.store-product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:22px}.store-product{border-radius:17px;overflow:hidden;background:white;border:1px solid #ecedf0;transition:transform .2s,box-shadow .2s}.store-product:hover{transform:translateY(-3px);box-shadow:0 10px 25px #344b5010}.store-product>img{width:100%;height:205px;object-fit:cover;background:#f1f4f2}.store-product>div{padding:19px}.store-product h3{font-size:15px;line-height:1.6;margin:0;color:#3d4d49}.store-product p{font-size:12px;color:#9aa49b;line-height:1.8;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.store-product footer{display:flex;justify-content:space-between;align-items:center;margin-top:20px}.store-product footer strong{font-size:21px;color:var(--theme-primary)}.store-product footer span{font-size:11px;color:#a0aaa5}@media(max-width:700px){.store-cover{padding:25px;min-height:235px}.store-identity{gap:14px}.store-identity h1{font-size:23px}.store-metrics{grid-template-columns:1fr;padding:8px 20px}.store-metrics>div{border-right:0;border-bottom:1px solid #edf0f2;padding:18px 0}.store-metrics strong{font-size:24px}.store-catalog>header{align-items:flex-start;flex-direction:column}.store-catalog>header .el-input{max-width:none}}
</style>
